import{_ as n,a0 as p,w as d,s as o,ao as h,I as l,x as s,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"12 個 ip 命令範例 | LCTT x X-CMD","titleTemplate":false,"description":"12 個 ip 命令範例 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"12 個 ip 命令範例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"12 個 ip 命令範例 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170915 12 ip Command Examples for Linux Users","title":"12 個 ip 命令範例","tag":"201801","desc":""},"relativePath":"201801/20170915 12 ip Command Examples for Linux Users.md","filePath":"[post].md"}'),c={name:"201801/20170915 12 ip Command Examples for Linux Users.md"};function r(g,i,u,k,b,m){const e=p("Link");return d(),o("div",null,[i[13]||(i[13]=h(`<h1 id="_12-個-ip-命令範例" tabindex="-1">12 個 ip 命令範例 <a class="header-anchor" href="#_12-個-ip-命令範例" aria-label="Permalink to “12 個 ip 命令範例”">​</a></h1><p>一年又一年，我們一直在使用 <code>ifconfig</code> 命令來執行網絡相關的任務，比如檢查和配置網卡信息。但是 <code>ifconfig</code> 已經不再被維護，並且在最近版本的 Linux 中被廢除了！ <code>ifconfig</code> 命令已經被 <code>ip</code> 命令所替代了。</p><p><code>ip</code> 命令跟 <code>ifconfig</code> 命令有些類似，但要強力的多，它有許多新功能。<code>ip</code> 命令完成很多 <code>ifconfig</code> 命令無法完成的任務。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/09/IP-command-examples-Linux.jpg" alt="IP-command-examples-Linux"></p><p>本教程將會討論 <code>ip</code> 命令的 12 中最常用法，讓我們開始吧。</p><h3 id="案例-1-檢查網卡信息" tabindex="-1">案例 1：檢查網卡信息 <a class="header-anchor" href="#案例-1-檢查網卡信息" aria-label="Permalink to “案例 1：檢查網卡信息”">​</a></h3><p>檢查網卡的諸如 IP 地址，子網等網絡信息，使用 <code>ip addr show</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$ ip addr show</span></span>
<span class="line"><span></span></span>
<span class="line"><span>或</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[linuxtechi@localhost]$ ip a s</span></span></code></pre></div><p>這會顯示系統中所有可用網卡的相關網絡信息，不過如果你想查看某塊網卡的信息，則命令為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$ ip addr show enp0s3</span></span></code></pre></div><p>這裏 <code>enp0s3</code> 是網卡的名字。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/09/IP-addr-show-commant-output.jpg" alt="IP-addr-show-commant-output"></p><h3 id="案例-2-啓用-禁用網卡" tabindex="-1">案例 2：啓用/禁用網卡 <a class="header-anchor" href="#案例-2-啓用-禁用網卡" aria-label="Permalink to “案例 2：啓用/禁用網卡”">​</a></h3><p>使用 <code>ip</code> 命令來啓用一個被禁用的網卡：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip link set enp0s3 up</span></span></code></pre></div><p>而要禁用網卡則使用 <code>down</code> 觸發器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip link set enp0s3 down</span></span></code></pre></div><h3 id="案例-3-為網卡分配-ip-地址以及其他網絡信息" tabindex="-1">案例 3：為網卡分配 IP 地址以及其他網絡信息 <a class="header-anchor" href="#案例-3-為網卡分配-ip-地址以及其他網絡信息" aria-label="Permalink to “案例 3：為網卡分配 IP 地址以及其他網絡信息”">​</a></h3><p>要為網卡分配 IP 地址，我們使用下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip addr add 192.168.0.50/255.255.255.0 dev enp0s3</span></span></code></pre></div><p>也可以使用 <code>ip</code> 命令來設置廣播地址。默認是沒有設置廣播地址的，設置廣播地址的命令為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$ sudo  ip addr add broadcast 192.168.0.255 dev enp0s3</span></span></code></pre></div><p>我們也可以使用下面命令來根據 IP 地址設置標準的廣播地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$  sudo ip addr add 192.168.0.10/24 brd + dev enp0s3</span></span></code></pre></div><p>如上面例子所示，我們可以使用 <code>brd</code> 代替 <code>broadcast</code> 來設置廣播地址。</p><h3 id="案例-4-刪除網卡中配置的-ip-地址" tabindex="-1">案例 4：刪除網卡中配置的 IP 地址 <a class="header-anchor" href="#案例-4-刪除網卡中配置的-ip-地址" aria-label="Permalink to “案例 4：刪除網卡中配置的 IP 地址”">​</a></h3><p>若想從網卡中刪掉某個 IP，使用如下 <code>ip</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip addr del 192.168.0.10/24 dev enp0s3</span></span></code></pre></div><h3 id="案例-5-為網卡添加別名-假設網卡名為-enp0s3" tabindex="-1">案例 5：為網卡添加別名（假設網卡名為 enp0s3） <a class="header-anchor" href="#案例-5-為網卡添加別名-假設網卡名為-enp0s3" aria-label="Permalink to “案例 5：為網卡添加別名（假設網卡名為 enp0s3）”">​</a></h3><p>添加別名，即為網卡添加不止一個 IP，執行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$  sudo ip addr add 192.168.0.20/24 dev enp0s3 label enp0s3:1</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/09/ip-command-add-alias-linux.jpg" alt="ip-command-add-alias-linux"></p><h3 id="案例-6-檢查路由-默認網關的信息" tabindex="-1">案例 6：檢查路由/默認網關的信息 <a class="header-anchor" href="#案例-6-檢查路由-默認網關的信息" aria-label="Permalink to “案例 6：檢查路由/默認網關的信息”">​</a></h3><p>查看路由信息會給我們顯示數據包到達目的地的路由路徑。要查看網絡路由信息，執行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$  ip route show</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/09/ip-route-command-output.jpg" alt="ip-route-command-output"></p><p>在上面輸出結果中，我們能夠看到所有網卡上數據包的路由信息。我們也可以獲取特定 IP 的路由信息，方法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip route get 192.168.0.1</span></span></code></pre></div><h3 id="案例-7-添加靜態路由" tabindex="-1">案例 7：添加靜態路由 <a class="header-anchor" href="#案例-7-添加靜態路由" aria-label="Permalink to “案例 7：添加靜態路由”">​</a></h3><p>我們也可以使用 IP 來修改數據包的默認路由。方法是使用 <code>ip route</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip route add default via 192.168.0.150/24</span></span></code></pre></div><p>這樣所有的網絡數據包通過 <code>192.168.0.150</code> 來轉發，而不是以前的默認路由了。若要修改某個網卡的默認路由，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip route add 172.16.32.32 via 192.168.0.150/24 dev enp0s3</span></span></code></pre></div><h3 id="案例-8-刪除默認路由" tabindex="-1">案例 8：刪除默認路由 <a class="header-anchor" href="#案例-8-刪除默認路由" aria-label="Permalink to “案例 8：刪除默認路由”">​</a></h3><p>要刪除之前設置的默認路由，打開終端然後運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$  sudo ip route del 192.168.0.150/24</span></span></code></pre></div><p><strong>注意：</strong> 用上面方法修改的默認路由只是臨時有效的，在系統重啓後所有的改動都會丟失。要永久修改路由，需要修改或創建 <code>route-enp0s3</code> 文件。將下面這行加入其中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$  sudo vi /etc/sysconfig/network-scripts/route-enp0s3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>172.16.32.32 via 192.168.0.150/24 dev enp0s3</span></span></code></pre></div><p>保存並退出該文件。</p><p>若你使用的是基於 Ubuntu 或 debian 的操作系統，則該要修改的文件為 <code>/etc/network/interfaces</code>，然後添加 <code>ip route add 172.16.32.32 via 192.168.0.150/24 dev enp0s3</code> 這行到文件末尾。</p><h3 id="案例-9-檢查所有的-arp-記錄" tabindex="-1">案例 9：檢查所有的 ARP 記錄 <a class="header-anchor" href="#案例-9-檢查所有的-arp-記錄" aria-label="Permalink to “案例 9：檢查所有的 ARP 記錄”">​</a></h3><p>ARP，是<ruby>地址解析協議<rt>Address Resolution Protocol</rt></ruby>的縮寫，用於將 IP 地址轉換為物理地址（也就是 MAC 地址）。所有的 IP 和其對應的 MAC 明細都存儲在一張表中，這張表叫做 ARP 緩存。</p><p>要查看 ARP 緩存中的記錄，即連接到局域網中設備的 MAC 地址，則使用如下 ip 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$  ip neigh</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/09/ip-neigh-command-linux.jpg" alt="ip-neigh-command-linux"></p><h3 id="案例-10-修改-arp-記錄" tabindex="-1">案例 10：修改 ARP 記錄 <a class="header-anchor" href="#案例-10-修改-arp-記錄" aria-label="Permalink to “案例 10：修改 ARP 記錄”">​</a></h3><p>刪除 ARP 記錄的命令為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip neigh del 192.168.0.106 dev enp0s3</span></span></code></pre></div><p>若想往 ARP 緩存中添加新記錄，則命令為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip neigh add 192.168.0.150 lladdr 33:1g:75:37:r3:84 dev enp0s3 nud perm</span></span></code></pre></div><p>這裏 <code>nud</code> 的意思是 “neghbour state”（網絡鄰居狀態），它的值可以是：</p><ul><li><code>perm</code> - 永久有效並且只能被管理員刪除</li><li><code>noarp</code> - 記錄有效，但在生命週期過期後就允許被刪除了</li><li><code>stale</code> - 記錄有效，但可能已經過期</li><li><code>reachable</code> - 記錄有效，但超時後就失效了</li></ul><h3 id="案例-11-查看網絡統計信息" tabindex="-1">案例 11：查看網絡統計信息 <a class="header-anchor" href="#案例-11-查看網絡統計信息" aria-label="Permalink to “案例 11：查看網絡統計信息”">​</a></h3><p>通過 <code>ip</code> 命令還能查看網絡的統計信息，比如所有網卡上傳輸的字節數和報文數，錯誤或丟棄的報文數等。使用 <code>ip -s link</code> 命令來查看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$ ip -s link</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/09/ip-s-command-linux.jpg" alt="ip-s-command-linux"></p><h3 id="案例-12-獲取幫助" tabindex="-1">案例 12：獲取幫助 <a class="header-anchor" href="#案例-12-獲取幫助" aria-label="Permalink to “案例 12：獲取幫助”">​</a></h3><p>若你想查看某個上面例子中沒有的選項，那麼你可以查看幫助。事實上對任何命令你都可以尋求幫助。要列出 <code>ip</code> 命令的所有可選項，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linuxtechi@localhost]$ ip help</span></span></code></pre></div><p>記住，<code>ip</code> 命令是一個對 Linux 系統管理來説特別重要的命令，學習並掌握它能夠讓配置網絡變得容易。本教程就此結束了，若有任何建議歡迎在下面留言框中留言。</p><hr>`,71)),l("p",null,[i[1]||(i[1]=s("via: ",-1)),a(e,{href:"https://www.linuxtechi.com/ip-command-examples-for-linux-users/"},{default:t(()=>[...i[0]||(i[0]=[s("https://www.linuxtechi.com/ip-command-examples-for-linux-users/",-1)])]),_:1})]),l("p",null,[i[5]||(i[5]=s("作者：",-1)),a(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...i[2]||(i[2]=[s("Pradeep Kumar",-1)])]),_:1}),i[6]||(i[6]=s(" 譯者：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...i[3]||(i[3]=[s("lujun9972",-1)])]),_:1}),i[7]||(i[7]=s(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...i[4]||(i[4]=[s("wxy",-1)])]),_:1})]),l("p",null,[i[10]||(i[10]=s("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[8]||(i[8]=[s("LCTT",-1)])]),_:1}),i[11]||(i[11]=s(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...i[9]||(i[9]=[s("Linux中國",-1)])]),_:1}),i[12]||(i[12]=s(" 榮譽推出",-1))])])}const C=n(c,[["render",r]]);export{y as __pageData,C as default};
